// ============================================================
// NO: modo  (cliente .31 - aba "Ler gerador (.31) - seletor")
// O QUE FAZ : traduz o botao clicado (inject) em comando para o repetidor
//             de 2 s ou para uma leitura unica.
// ENTRADA   : msg.topic = "auto" | "off" | "once" (vem dos 3 nos inject).
// SAIDAS    : 1 -> liga o trigger "repete a cada 2 s"
//             2 -> para o trigger (msg.reset = true)
//             3 -> dispara uma unica leitura (vai direto ao msg.url)
// ESTADO    : nao guarda nada; o estado do seletor para o PLC e gravado
//             pelo no "estado do seletor -> PLC", que recebe o mesmo clique.
// Autor: Reginaldo Lobo  -  Projeto: Banco de Testes - Gerador Diesel
// ============================================================
// Seletor de modo. Estado inicial: DESLIGADO (nada lê até você escolher).
// msg.topic: "auto" = liga leitura a cada 2 s | "off" = desliga | "once" = uma leitura agora
const t = msg.topic;
if (t === "auto") {
  // AUTOMATICO: o trigger repete a mensagem a cada 2 s ate receber reset.
  node.status({ fill: "green", shape: "dot", text: "AUTOMÁTICO ligado (2 s)" });
  return [{ payload: "1" }, null, null];        // saída 1: liga o repetidor
}
if (t === "off") {
  // DESLIGAR: msg.reset = true faz o trigger cancelar a repeticao sem enviar nada.
  node.status({ fill: "grey", shape: "ring", text: "DESLIGADO" });
  return [null, { reset: true, payload: "0" }, null];  // saída 2: para o repetidor
}
if (t === "once") {
  // LER AGORA: nao mexe no repetidor; se o automatico estiver ligado, continua ligado.
  return [null, null, { payload: "1" }];        // saída 3: leitura única
}
// Qualquer outro topic e ignorado (nenhuma saida).
return null;

// ============================================================
// NO: estado do seletor -> PLC
// O QUE FAZ : a cada clique de botao (e uma vez na partida do Node-RED, pelo
//             inject "inicio = DESLIGADO", item C3) grava no DB52 o estado do
//             seletor, para o PLC e a tela saberem se a leitura esta ligada.
// ENTRADA   : msg.topic = "auto" | "off" | "once".
// SAIDA     : 2 mensagens para o no S7 (uma por variavel da vartable):
//             Ints_Seletor -> DB52.DBW8 (seletor) e DBW10 (errosConsecutivos)
//             Bits_Status  -> DB52.DBB0 (byte inteiro de status)
// CONTEXTO  : flow.sel  = seletor atual (lido pelo no "mapeia JSON -> DB52")
//             flow.errs = erros consecutivos (zerado ao desligar)
// OBS       : Bits_Status grava o BYTE inteiro: 4 = so o bit 2 (statusAutomatico).
//             Os bits LeituraOk/Http200 voltam a ser escritos no proximo ciclo.
// Autor: Reginaldo Lobo  -  Projeto: Banco de Testes - Gerador Diesel
// ============================================================
// Estado do seletor para o PLC: 0 = desligado | 1 = automatico | 2 = ultima foi leitura unica
const m = { auto: 1, off: 0, once: 2 }[msg.topic];
if (m === undefined) return null;                // topic desconhecido: nao grava nada
flow.set("sel", m);
if (m === 0) { flow.set("errs", 0); }            // ao desligar, zera o contador de erros
// Array dentro de array: varias mensagens pela MESMA saida (uma por variavel S7).
// Ints_Seletor e um endereco-array (INT8.2), por isso o payload vai como [[seletor, erros]].
return [[{ variable: "Ints_Seletor", payload: [[m, flow.get("errs") || 0]] },
         { variable: "Bits_Status", payload: m === 1 ? 4 : 0 }]];

// ============================================================
// NO: mapeia JSON -> DB52
// O QUE FAZ : converte a resposta do servidor DSE (GET /api/gerador) nas
//             variaveis do DB52 "db52_BancoTeste2_DSE" (DB nao otimizado,
//             acesso por offset via PUT/GET) e gera uma mensagem por variavel
//             da vartable do no S7.
// QUANDO    : a cada resposta do GET (2 s no automatico, ou 1 vez no LER AGORA)
//             e a cada falha de rede vinda do Catch.
// ENTRADA   : msg.statusCode (200, 503, codigo de erro ou 0) e msg.payload
//             (objeto JSON do servidor, ou null em falha).
// SAIDA     : [[{variable, payload}, ...]] -> no "Escreve DB52".
// REGRA DE OURO (fail-safe):
//   - Dado FRESCO (HTTP 200, ok = true e idade <= 10 s): grava tudo.
//   - Qualquer falha: grava SO status, seletor/erros e heartbeat. As medidas
//     do DB52 ficam com o ultimo valor bom; a tela deve olhar statusLeituraOk.
// CONTEXTO  : flow.hb (heartbeat), flow.errs (erros consecutivos), flow.sel (seletor).
// VERSAO 2  : itens da revisao C2 (bit de falha da ECU), C4 (bit servidor online),
//             C5 (relogio com 19 caracteres) e C8 (sem recalculo de qtdNulos).
// Autor: Reginaldo Lobo  -  Projeto: Banco de Testes - Gerador Diesel
// ============================================================
// Mapeia /api/gerador -> DB52 (nao otimizado). Uma mensagem por bloco de variaveis.
const IDADE_MAX = 10;            // s: dado mais velho que isso = "dados antigos", nao grava medidas
// Ordem FIXA das 42 medidas Real gravadas a partir de DB52.DBD28 (vartable "Reais" = REAL28.42).
// A posicao no array define o offset no DB: indice i -> DBD(28 + 4*i). Nao reordenar.
const REAIS = ["tensaoL1L2", "tensaoL2L3", "tensaoL3L1", "tensaoFFMedia", "tensaoL1N", "tensaoL2N", "tensaoL3N", "tensaoFNMedia", "correnteL1", "correnteL2", "correnteL3", "corrente", "frequencia", "rpm", "kw", "kva", "kvar", "fp", "percCarga", "kwL1", "kwL2", "kwL3", "fpL1", "fpL2", "fpL3", "tempAguaC", "bateria", "alternador", "nivelCombustivel", "horasMotor", "kwh", "kvah", "kvarh", "desequilibrioTensaoPct", "desequilibrioCorrentePct", "kvaL1", "kvaL2", "kvaL3", "kvarL1", "kvarL2", "kvarL3", "percKvar"];

// ================= CLASSIFICACAO DA LEITURA =================
// http200 : o servidor respondeu 200 com um objeto JSON.
// okApi   : alem disso, o servidor declarou ok = true e informou a idade do dado.
// fresco  : alem disso, a idade do dado do DSE esta dentro do limite (10 s).
// Um 503 do servidor (DSE sem dado) cai em http200 = false.
// servidorOnline (v2, item C4): o servidor respondeu com QUALQUER codigo HTTP
//           (200, 503...). Falha de rede ou timeout chegam do Catch com
//           statusCode = 0. Com ele o PLC separa "servidor/rede fora" (0) de
//           "DSE sem dado" (1 com statusLeituraOk = 0).
const p = msg.payload;
const http200 = (msg.statusCode === 200) && p && typeof p === "object";
const servidorOnline = typeof msg.statusCode === "number" && msg.statusCode > 0;
const okApi = http200 && p.ok === true && typeof p.idadeSegundos === "number";
const fresco = okApi && p.idadeSegundos <= IDADE_MAX;

// ================= CONTADORES DE SUPERVISAO =================
// heartbeat: soma 1 a cada resposta processada (boa ou ruim). O PLC usa como
//            watchdog: se parar de mudar, o Node-RED da .31 parou de gravar.
//            Volta a 1 perto do limite do DInt para nunca estourar.
// errs     : ciclos seguidos sem dado fresco; zera na primeira leitura boa;
//            limitado ao maximo de um Int (32767).
let hb = (flow.get("hb") || 0) + 1; if (hb > 2147483000) hb = 1; flow.set("hb", hb);
let errs = flow.get("errs") || 0;
errs = fresco ? 0 : Math.min(errs + 1, 32767); flow.set("errs", errs);
const sel = flow.get("sel") || 0;

// ================= AUXILIARES DE ESCRITA =================
// w(variavel, valor): empilha uma mensagem para o no S7. Enderecos-array da
//                     vartable (ex.: INT4.2, REAL28.42) exigem payload [[...]].
// bits([b0, b1, ...]): monta um byte; o 1o item vira o bit 0.
const out = [];
const w = (v, val) => out.push({ variable: v, payload: Array.isArray(val) ? [val] : val });  // endereco-array do S7 exige [[...]]
const bits = a => a.reduce((s, b, i) => s | (b ? (1 << i) : 0), 0);

// ================= STATUS (SEMPRE GRAVADO) =================
// DB52.DBB0: bit0 statusLeituraOk, bit1 statusHttp200, bit2 statusAutomatico,
//            bit3 statusDadosAntigos (servidor ok, mas dado acima de 10 s),
//            bit4 statusServidorOnline (servidor respondeu HTTP, mesmo 503).
// DB52.DBW8/DBW10: seletor e errosConsecutivos.  DB52.DBD12: heartbeat.
// Estado de comunicacao: grava SEMPRE (inclusive em falha)
w("Bits_Status", bits([fresco, !!http200, sel === 1, okApi && !fresco, servidorOnline]));
w("Ints_Seletor", [sel, errs]);
w("Dint_Heartbeat", hb);

// ================= DADOS DO GERADOR (SO COM DADO FRESCO) =================
// Campo nulo ou invalido no JSON vira 0 no DB52 e soma em qtdNulos, para a
// tela saber que aquele 0 pode ser "nao medido" e nao um valor real.
// Textos vao sem acento (String S7 so aceita ASCII) e cortados no tamanho
// declarado no DB.
if (fresco) {
  let nulos = 0;
  const num = v => (typeof v === "number" && isFinite(v)) ? v : (nulos++, 0);
  const sem = s => String(s == null ? "" : s).normalize("NFD").replace(/[̀-ͯ]/g, "").replace(/[^\x20-\x7E]/g, "?");
  const L = p.leds || {};
  const al = Array.isArray(p.alarmes) ? p.alarmes : [];
  // DB52.DBB1 alarmes (bit0 tem alarme, bit1 aviso, bit2 desligamento, bit3 trip eletrico,
  //           bit4 desligamento controlado); DBB2 LEDs; DBB3 saidas.
  // saidaFalhaEcu (v2, item C2): so com falhasEcu.quantidade > 0. O servidor manda
  // falhasEcu como objeto mesmo sem falha; o objeto sozinho nao acende o bit.
  w("Bits_Dados", [
    bits([p.temAlarme, p.alarmeAviso, p.alarmeDesligamento, p.alarmeTripEletrico, p.alarmeDesligamentoControlado]),
    bits([L.stop, L.manual, L.teste, L.auto, L.disjuntorGerador, L.geradorDisponivel]),
    bits([p.saidaCombustivel, p.saidaPartida, p.falhasEcu && p.falhasEcu.quantidade > 0])
  ]);
  w("Ints_Modo", [Math.trunc(num(p.modoCodigo)), Math.round(p.idadeSegundos)]);        // DBW4 modo, DBW6 idade [s]
  w("Dint_Horas", [Math.trunc(num(p.horasMotorSegundos)), Math.trunc(num(p.partidas))]); // DBD16 horas [s], DBD20 partidas
  w("Reais", REAIS.map(k => num(p[k])));                                                // DBD28..DBD192, 42 Reals
  w("Ints_Cont", [Math.min(nulos, 32767), al.length]);   // depois de todos os num(): qtdNulos completo
  w("Str_Modo", sem(p.modo).slice(0, 16));                                     // DB52 S196, 16 caracteres
  w("Str_Modelo", sem(p.dse && p.dse.modeloConfigurado).slice(0, 12));         // DB52 S214, 12 caracteres
  w("Str_Alarme", sem(al.map(a => a.nome).join("; ")).slice(0, 60));           // DB52 S228, 60 caracteres
  // Relogio (v2, item C5): hora LOCAL do DSE no formato AAAA-MM-DDTHH:MM:SS (19 caracteres).
  // Remove "Z" e milissegundos caso o servidor seja anterior a v3.2.
  w("Str_Relogio", sem(p.relogioDse).replace(/Z$/, "").slice(0, 19));          // DB52 S290, String[20]
}
// ================= STATUS VISUAL DO NO =================
// Verde: gravou dado fresco. Vermelho: motivo da falha + contador de erros.
node.status({ fill: fresco ? "green" : "red", shape: "dot",
  text: (fresco ? "gravado hb=" + hb : (http200 ? (okApi ? "dados antigos " + p.idadeSegundos + "s" : "servidor ok=false") : "HTTP " + (msg.statusCode || "?"))) + " | erros " + errs });
return [out];

// ============================================================
// NO: falha -> comunicacao ruim
// O QUE FAZ : recebe do Catch os erros de rede do GET (servidor desligado,
//             cabo, timeout de 1,5 s) e entrega ao mapeamento como "sem resposta".
// RESULTADO : o no "mapeia JSON -> DB52" grava so o status
//             (statusLeituraOk = 0, errosConsecutivos + 1, heartbeat + 1)
//             e NAO sobrescreve as medidas ja gravadas no DB52.
// OBS (v2)  : o GET esta com "Somente envie respostas nao-2xx para o no de
//             Captura" marcado (item C1): erro de rede chega SO por aqui, nao em
//             dobro. Respostas HTTP 503 continuam pela saida normal do GET.
// Autor: Reginaldo Lobo  -  Projeto: Banco de Testes - Gerador Diesel
// ============================================================
// Falha de rede/timeout no GET (catch): marca comunicacao ruim sem apagar as ultimas medidas.
msg.payload = null; msg.statusCode = 0;         // statusCode 0 = "sem resposta HTTP"
return msg;
